final class PlayerState: NSObject {
    @objc dynamic var volume = 20
}
final class VolumeMonitor {
    let player = PlayerState()
    var token: NSKeyValueObservation?
    var values: [Int] = []
    func start() {
        token?.invalidate()
        token = player.observe(\.volume, options: [.new]) {
            [weak self] _, change in
            self?.values.append(change.newValue ?? -1)
        }
    }
}
let monitor = VolumeMonitor()
monitor.start()
monitor.start()
monitor.player.volume = 35
print(monitor.values)

Вывод: [35]. Повторный start заменяет наблюдение, а не добавляет второе; callback не удерживает monitor.

