import Foundation
final class PlayerState: NSObject {
    @objc dynamic var volume = 20
    @objc dynamic func status() -> NSString { "Готов" }
}
let player = PlayerState()
let token = player.observe(\.volume, options: [.old, .new]) { _, change in
    let old = change.oldValue ?? -1
    let new = change.newValue ?? -1
    if old != new { print("\(old) -> \(new)") }
}
player.volume = 20
player.volume = 35
token.invalidate()

Вывод: 20 -> 35. Наблюдатель сам отбрасывает событие без изменения значения; KVO не заменяет это условие.

