final class VolumeState: NSObject {
    @objc dynamic var volume = 20
}
let volumeState = VolumeState()
let key = #keyPath(VolumeState.volume)
volumeState.setValue(35, forKey: key)
print(volumeState.value(forKey: key) as? Int ?? -1)

Первый пример выводит true, второй — 35. #keyPath использует конкретную NSObject-модель VolumeState с volume; результат KVC проверяется приведением.
